CREATE TABLE IF NOT EXISTS "Device" (
  "id" TEXT NOT NULL PRIMARY KEY DEFAULT gen_random_uuid(),
  "device" TEXT,
  "model" TEXT,
  "modelNumber" TEXT,
  "serialNumber" TEXT,
  "ip" TEXT,
  "battery" TEXT,
  "status" TEXT,
  "bw" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

DELETE FROM "Device";
